const sandCrystalSheet=new Image();sandCrystalSheet.assetSrc='assets/desert-crystal-spirit-v1.png';
function beginSandCrystal(e){let angle=Math.atan2(p.y-e.y,p.x-e.x);e.state='attack';e.elapsed=0;e.facing=Math.cos(angle)-Math.sin(angle)<0?-1:1;e.attack={pattern:'crystalCompass',bespoke:true,windup:1,origin:{x:e.x,y:e.y},angle,waves:[{at:1,angle,done:false},{at:1.7,angle:angle+Math.PI/4,done:false}]};}
function sandCrystalLaneContains(origin,angle,point){let dx=point.x-origin.x,dy=point.y-origin.y,x=dx*Math.cos(angle)+dy*Math.sin(angle),y=-dx*Math.sin(angle)+dy*Math.cos(angle);return x>=45-1e-8&&x<=330+1e-8&&Math.abs(y)<=18+1e-8;}
function sandCrystalWaveContains(origin,angle,point){for(let i=0;i<4;i++)if(sandCrystalLaneContains(origin,angle+i*Math.PI/2,point))return true;return false;}
const sandCrystalAnimateBase=animateEnemy;animateEnemy=(e,dt)=>{
 if(e.species!=='r4e1')return sandCrystalAnimateBase(e,dt);if(e.hp<=0||e.reactionStun>0||paused||dead||!Number.isFinite(dt)||dt<=0)return;
 e.anim+=dt;e.flash=Math.max(0,(e.flash||0)-dt);e.slow=Math.max(0,(e.slow||0)-dt);
 if(e.attack?.pattern!=='crystalCompass'){e.t-=dt;e.nav=(e.nav||0)-dt;let distance=dist(e,p),clear=lineClear(e,p);if(e.t<=0&&distance<=320&&clear)beginSandCrystal(e);else{e.state='idle';if(distance>750&&!e.aware)return;if(distance<=200&&clear)return;if(e.nav<=0){e.nav=.65;e.path=clear?[{x:p.x,y:p.y}]:findPath(e,p);}let to=e.path?.[0];if(to){let dx=to.x-e.x,dy=to.y-e.y,len=Math.hypot(dx,dy);if(len<10)e.path.shift();else{let step=Math.min(len,78*(e.slow>0?.35:1)*dt);e.state=moveActor(e,dx/len*step,dy/len*step,18)>.1?'walk':'idle';e.facing=dx-dy<0?-1:1;}}return;}}
 e.elapsed=Math.round((e.elapsed+dt)*1e6)/1e6;let a=e.attack;for(let wave of a.waves)if(!wave.done&&e.elapsed>=wave.at){wave.done=true;if(sandCrystalWaveContains(a.origin,wave.angle,p)&&lineClear(a.origin,p))hurt(46);playSound('arc',a.origin.x,a.origin.y);burst(a.origin.x,a.origin.y,35,'#8fe9e0');}if(e.elapsed>=2.5){e.attack=null;e.state='idle';e.t=2.4;}
};
const sandCrystalDrawBase=drawRegionEnemy;drawRegionEnemy=(e,size)=>{if(e.species!=='r4e1'||!sandCrystalSheet.complete||!sandCrystalSheet.naturalWidth)return sandCrystalDrawBase(e,size);let f=spriteFrame(e.state,e.anim);if(e.hp>0&&e.attack?.pattern==='crystalCompass')f={row:2,col:e.elapsed<.5?0:e.elapsed<1?1:e.elapsed<1.9?2:3};let q=project(e.x,e.y),sw=sandCrystalSheet.naturalWidth/4,sh=sandCrystalSheet.naturalHeight/3,w=115,h=w*sh/sw;ctx.save();ctx.translate(q.x,q.y);ctx.scale(e.facing||1,1);ctx.filter=e.flash>0?'brightness(1.8)':'none';if(typeof drawPreparedEnemySprite==='function')drawPreparedEnemySprite(ctx,sandCrystalSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*.85,w,h);else ctx.drawImage(sandCrystalSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*.85,w,h);ctx.restore();return true;};
const sandCrystalSizeBase=enemyVisualSize;enemyVisualSize=e=>e.species==='r4e1'?100:sandCrystalSizeBase(e);
function paintSandCrystalLane(origin,angle,flash){let c=Math.cos(angle),s=Math.sin(angle),point=(along,side)=>({x:origin.x+c*along-s*side,y:origin.y+s*along+c*side});ctx.save();ctx.beginPath();let coords=[];for(let side of [-18,18]){let start=point(45,side),last=start;if(!lineClear(origin,start)){ctx.restore();return;}let end=point(330,side);if(lineClear(origin,end))last=end;else{let low=45,high=330;for(let step=0;step<7;step++){let mid=(low+high)/2,next=point(mid,side);if(lineClear(origin,next)){low=mid;last=next;}else high=mid;}}coords.push([start,last]);}let shape=[coords[0][0],coords[0][1],coords[1][1],coords[1][0]];for(let [i,pos]of shape.entries()){let q=project(pos.x,pos.y);if(i)ctx.lineTo(q.x,q.y);else ctx.moveTo(q.x,q.y);}ctx.closePath();ctx.strokeStyle=flash?'#e5ffff':'#e9c77e';ctx.fillStyle=flash?'#7fece080':'#d5b36a24';ctx.lineWidth=flash?3:1;ctx.fill();ctx.stroke();ctx.restore();}
const sandCrystalGroundBase=drawGroundEffects;drawGroundEffects=()=>{sandCrystalGroundBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r4e1'):enemies)){let a=e.attack;if(e.species!=='r4e1'||e.hp<=0||a?.pattern!=='crystalCompass'||!visibleAt(a.origin.x,a.origin.y))continue;for(let [index,w]of a.waves.entries()){let flash=w.done&&e.elapsed<w.at+.16;if(w.done&&!flash||index===1&&!a.waves[0].done)continue;for(let i=0;i<4;i++)paintSandCrystalLane(a.origin,w.angle+i*Math.PI/2,flash);}}};
